CREATE TABLE IF NOT EXISTS produit_fiche (produit_id INT NOT NULL PRIMARY KEY,categorie VARCHAR(120) DEFAULT NULL,marque VARCHAR(120) DEFAULT NULL,reference_fabricant VARCHAR(140) DEFAULT NULL,description_courte VARCHAR(500) DEFAULT NULL,description_longue TEXT DEFAULT NULL,garantie VARCHAR(120) DEFAULT NULL,pays_origine VARCHAR(120) DEFAULT NULL,delai_livraison VARCHAR(160) DEFAULT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_product_sheet_product FOREIGN KEY (produit_id) REFERENCES produit(id_produit) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS produit_specification (id INT AUTO_INCREMENT PRIMARY KEY,produit_id INT NOT NULL,libelle VARCHAR(160) NOT NULL,valeur VARCHAR(500) NOT NULL,position INT NOT NULL DEFAULT 0,INDEX idx_product_spec_product (produit_id,position),CONSTRAINT fk_product_spec_product FOREIGN KEY (produit_id) REFERENCES produit(id_produit) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversations_boutique (id INT AUTO_INCREMENT PRIMARY KEY,visitor_token VARCHAR(80) NOT NULL,nom_visiteur VARCHAR(160) DEFAULT NULL,email_visiteur VARCHAR(190) DEFAULT NULL,produit_id INT DEFAULT NULL,statut VARCHAR(30) NOT NULL DEFAULT 'ouverte',assigned_user_id INT DEFAULT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uniq_shop_chat_visitor (visitor_token),INDEX idx_shop_chat_status_date (statut,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS messages_boutique (id INT AUTO_INCREMENT PRIMARY KEY,conversation_id INT NOT NULL,expediteur VARCHAR(20) NOT NULL,user_id INT DEFAULT NULL,message TEXT NOT NULL,lu_at DATETIME DEFAULT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_shop_message_conversation (conversation_id,id),CONSTRAINT fk_shop_message_conversation FOREIGN KEY (conversation_id) REFERENCES conversations_boutique(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
